pill <- function(text, class = "") tags$span(class = paste("pill", class), text)
panel <- function(title, ..., class = "") tags$section(class = paste("panel", class), tags$h3(title), ...)
empty_state <- function(title, text) tags$div(class = "empty-state", tags$div(class = "empty-icon", "✧"), tags$h3(title), tags$p(text))
sm_icon <- function(name) {
  paths <- list(discover = "M12 3l3 6 6 3-6 3-3 6-3-6-6-3 6-3z", profile = "M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M5 21v-2a7 7 0 0 1 14 0v2", questions = "M8 4h8l4 4v12H4V4h4M8 12h8M8 16h5", interests = "M5 19C3 5 18 3 21 3c0 14-7 20-16 16M5 19l10-10M11 13V8M11 13h5", chat = "M4 4h16v12H9l-5 4V4M8 9h8M8 12h5", guide = "M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 11v6M12 7v1", privacy = "M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3", arrow = "M5 12h14M14 7l5 5-5 5")
  tags$svg(class = "sm-icon", width = "22", height = "22", viewBox = "0 0 24 24", fill = "none", stroke = "currentColor", `stroke-width` = "1.5", `stroke-linecap` = "round", `stroke-linejoin` = "round", `aria-hidden` = "true", tags$path(d = paths[[name]] %||% paths$discover))
}
brand_mark <- function() tags$svg(class = "brand-mark", width = "40", height = "44", viewBox = "0 0 44 44", fill = "none", `aria-hidden` = "true", tags$path(d = "M25 7C9 6 4 21 15 30c6 5 17 2 18-6C34 11 17 11 14 20c-3 9 4 17 13 17", stroke = "currentColor", `stroke-width` = "2.2", `stroke-linecap` = "round"))
nav_title <- function(icon, text) tagList(sm_icon(icon), tags$span(text))
demo_portrait <- function(person = "nonbinary", class = "", label = "Fictional demo portrait") tags$div(class = paste("demo-portrait portrait-", person, " ", class, sep = ""), role = "img", `aria-label` = label)
app_ui <- function(demo_mode, algorithms, questionnaires) {
  fluidPage(theme = bs_theme(version = 5, bg = "#F4EDE6", fg = "#364F4B", primary = "#364F4B", secondary = "#D58B80", base_font = "system-ui"),
    tags$head(tags$title("SoulMatch · connection, considered"), tags$meta(name = "viewport", content = "width=device-width, initial-scale=1"), includeCSS(file.path(getOption("soulmatch.www_dir", "www"), "app.css")), includeScript(file.path(getOption("soulmatch.www_dir", "www"), "app.js"))),
    tags$header(class = "site-header", tags$div(class = "brand", brand_mark(), tags$span("SoulMatch"), tags$span(class = "brand-caption", "CONNECTION, CONSIDERED")), uiOutput("session_controls")),
    if (demo_mode) tags$div(class = "demo-strip", "A fictional community for exploring SoulMatch · AI-created demo portraits · Your own photos stay private"),
    uiOutput("screen"), tags$footer(tags$span("SoulMatch  /  Modern Romance"), tags$span("A little science. A little serendipity. A lot of you.")))
}
auth_ui <- function(demo_mode) {
  tags$main(class = "auth-layout",
    tags$div(class = "auth-story", pill("LOVE, FRIENDSHIP & THE SPACE IN BETWEEN", "lavender"), tags$h1("Find your kind", tags$br(), tags$em("of connection.")), tags$p("A thoughtful place to meet people who feel like your people. Start with who you are. Leave room for who you might find."),
      tags$div(class = "auth-portraits", demo_portrait("female"), demo_portrait("male"), demo_portrait("nonbinary")),
      tags$div(class = "editorial-caption", tags$span("Different stories."), tags$em("Something in common.")),
      tags$div(class = "auth-points", tags$p(tags$b("01"), " A little self-discovery"), tags$p(tags$b("02"), " Love, friends, or both"), tags$p(tags$b("03"), " A connection you choose together"))),
    panel("Something good could start here.", tags$p(class = "muted", "Welcome to a more considered way to connect."), textInput("username", "Your username", placeholder = "e.g. alex"), passwordInput("password", "Your password"), actionButton("login", "Welcome back →", class = "btn-primary full-width"), tags$div(class = "form-divider", tags$span("OR BEGIN YOUR STORY")),
      checkboxInput("adult", "I am at least 18 years old", FALSE), actionButton("register", "Create my account", class = "btn-outline-primary full-width"), tags$p(class = "fine-print", "Choose a username with 3–30 letters, numbers or underscores, and a password with at least 12 characters."),
      if (demo_mode) tags$details(class = "demo-login", tags$summary("Take a look around first"), tags$p("Username: alex · Password: SoulMatchDemo!2026"), tags$p("To try a conversation, sign in as maya in a second browser session. All eight fictional demo accounts use this password.")),
      tags$div(class = "trust-note", sm_icon("privacy"), tags$span("Private answers. Mutual choice. Your own pace."))))
}
member_ui <- function(algorithms, questionnaires, initial_tab = "discover") {
  tags$main(class = "workspace", uiOutput("welcome"),
    tabsetPanel(id = "main_nav", type = "pills", selected = initial_tab,
      tabPanel(nav_title("discover", "Discover"), value = "discover",
        tags$div(class = "section-intro discovery-intro", tags$div(pill("CONNECTION, WITH A LITTLE MORE MEANING", "eyebrow"), tags$h1("A little closer to", tags$em(" your people.")), tags$p("A new love. A new friend. A good reason to say hello.")), uiOutput("mode_picker")),
        uiOutput("onboarding_notice"), tags$div(class = "discovery-layout",
          tags$aside(class = "discovery-tools", panel("Make room for possibility", tags$p("There is more to a connection than a perfect checklist."), tags$div(class = "mode-note", uiOutput("mode_note")), tags$hr(), selectInput("algorithm", "Your discovery lens", choices = setNames(names(algorithms), vapply(algorithms, `[[`, "", "label"))), conditionalPanel("input.discovery_mode == 'love'", checkboxInput("explore", "Surprise me a little", TRUE)), actionButton("refresh", "New perspective ↻", class = "btn-outline-primary full-width"), tags$details(class = "method-detail", tags$summary("About this lens"), uiOutput("algorithm_note"))),
            tags$div(class = "small-editorial", tags$span("A THOUGHT TO KEEP"), tags$p("The right kind of connection leaves room to be yourself."))),
          tags$div(class = "discovery-center", uiOutput("candidate_card")),
          tags$aside(class = "connection-sidebar", panel("It starts with two yeses.", tags$div(class = "mutual-art", tags$span("you"), tags$i("↔"), tags$span("them")), tags$p("Express interest. When the feeling is mutual, a conversation opens."), tags$div(class = "trust-note", sm_icon("privacy"), tags$span("No unsolicited messages."))), panel("A fuller picture of you", tags$p("Give connection a little more to work with."), uiOutput("journey_summary"), actionButton("open_interests", "Explore self-discovery →", class = "btn-outline-primary full-width"))))),
      tabPanel(nav_title("profile", "My profile"), value = "profile", tags$div(class = "section-intro", pill("BE YOURSELF HERE", "eyebrow"), tags$h1("A story only", tags$em(" you can tell.")), tags$p("Your identity, your intentions, your own kind of life.")), uiOutput("profile_editor")),
      tabPanel(nav_title("questions", "Self-discovery"), value = "questions",
        tags$div(class = "section-intro", pill("A LITTLE MORE YOU", "eyebrow"), tags$h1("Get to know", tags$em(" yourself.")), tags$p("Small discoveries. A fuller picture. Choose a module and go at your own pace.")),
        tags$div(class = "privacy-banner", sm_icon("privacy"), tags$span("Your answers belong to you. Other people see aggregate fit metrics, never your responses.")),
        tags$div(style = "display:none", textOutput("active_module_state")),
        conditionalPanel("output.active_module_state === ''", uiOutput("discovery_modules")),
        conditionalPanel("output.active_module_state !== ''", tags$div(class = "module-toolbar", actionButton("back_to_modules", "← All modules", class = "btn-outline-primary"), uiOutput("active_module_title"))),
        conditionalPanel("output.active_module_state === 'reflection'", tags$div(class = "reflection-workspace",
          panel("Your reflection", uiOutput("question_form"), tags$div(class = "wizard-actions", actionButton("previous_question_page", "← Back", class = "btn-outline-primary"), actionButton("save_question_draft", "Save for later", class = "btn-outline-primary"), actionButton("save_question_page", "Save & continue →", class = "btn-primary"))),
          tags$aside(class = "reflection-note", sm_icon("questions"), tags$h3("There is no perfect answer."), tags$p("Choose what feels most like you today. You can revisit every module."), tags$p(class = "fine-print", "These short tools are experimental. Fit metrics describe patterns, not diagnoses or a promise of chemistry.")))),
        conditionalPanel("output.active_module_state === 'interests'", interestsModuleUI("interests")),
        conditionalPanel("output.active_module_state === 'height'", heightModuleUI("height"))),
      tabPanel(nav_title("interests", "My world"), value = "interests",
        tags$div(class = "section-intro", pill("THE PEOPLE YOU CHOSE", "eyebrow"), tags$h1("Your world,", tags$em(" taking shape.")), tags$p("Your connection requests and mutual connections, together in one place.")),
        uiOutput("world_summary"),
        tags$div(class = "world-toolbar", radioButtons("world_filter", "Connection status", c("Everyone" = "all", "Mutual interest" = "mutual", "Requests sent" = "pending"), "all", inline = TRUE), selectInput("world_mode", "Connection space", c("Love & Friends" = "all", "Love" = "love", "Friends" = "friends"), "all")),
        uiOutput("world_cards"), tags$p(class = "metrics-footnote", "Overall fit uses the Thoughtful balance lens. Fit metrics are experimental points out of 100, not a probability of attraction or a relationship. Missing component comparisons are shown as unavailable. Individual questionnaire answers and exact preferences stay private.")),
      tabPanel(nav_title("chat", "Messages"), value = "chat", tags$div(class = "section-intro", pill("A MUTUAL BEGINNING", "eyebrow"), tags$h1("A little hello.", tags$em(" A new possibility.")), tags$p("Your Love and Friends conversations stay separate.")),
        tags$div(class = "chat-layout", panel("Your connections", uiOutput("connection_picker")), panel("Make a little conversation", uiOutput("chat_header"), uiOutput("messages"), tags$div(class = "message-composer", textAreaInput("message", "Your message", placeholder = "Ask about something that made you curious…", rows = 2), actionButton("send", "Send ↗", class = "btn-primary")),
          tags$details(class = "safety-details", tags$summary("Safety & control"), textInput("report_reason", "What would you like to report?"), actionButton("block_chat", "Block this person", class = "btn-outline-secondary"), actionButton("report_chat", "Report & block", class = "btn-outline-secondary"))))),
      tabPanel(nav_title("guide", "Our approach"), value = "methods", methods_ui(questionnaires)),
      tabPanel(nav_title("privacy", "Your privacy"), value = "privacy", privacy_ui()))
  )
}
privacy_ui <- function() panel("Your data, your choice", tags$p("Your answers, interests, preferences, optional height-story responses, photos, interactions and conversations are stored privately on the app host. Raw questionnaire answers, exact preferences and income stay off your profile."), tags$p("Only an approximate height estimate you explicitly enable can be shown or used in Love suggestions. No direct height entry is requested. Weight is never collected or used."), tags$p("Love and Friends are separate, opt-in spaces. You can use either or both, and pause either in your profile. Paused conversations become unavailable until both people enable that mode again. A block applies across both spaces."), tags$p("Model-development consent is optional and off by default. Both people must opt in before a view can be exported for model development. Withdrawal excludes earlier data from future exports; it does not revoke existing exports or retrain models."), tags$p("This local pilot has no staffed moderation queue. Reports are saved for the operator. Chats are access controlled, not end-to-end encrypted."), tags$hr(), passwordInput("delete_password", "Confirm your password"), checkboxInput("delete_ack", "Permanently delete my account and associated records", FALSE), actionButton("delete_account", "Delete my account", class = "btn-outline-danger"))
methods_ui <- function(questionnaires) tags$div(class = "methods-grid",
  panel("Connection is a possibility.", tags$p("Fit points describe an experimental ranking, not your worth or a verified chance of a relationship. A high score is an invitation to explore."), tags$p("The app cannot yet estimate whether another person will be interested. An optional future pilot model requires real decisions, calibration and independent evaluation.")),
  panel("A little science. Room to learn.", tags$p("Your personality introduction uses two public-domain IPIP items per Big Five domain. This custom 10-item screener is experimental and is not the BFI-2."), tags$p("Communication, closeness, and everyday flexibility each have four optional original questions. Their predictive value has not been established."), tags$p("Interests, enjoyment, frequency, partner preferences and lifestyle are captured separately. Similarity and complementarity are research features, not universal rules.")),
  panel("Two spaces. Your choice.", tags$p("Love respects mutual romantic gender interests and firm partner boundaries. Friends uses mutual opt-in, shared interests and lifestyle context, without applying romantic preferences."), tags$p("Every algorithm respects adult eligibility, mode choice and blocks. Chat requires a mutual connection within the same space.")),
  panel("An evolving toolkit", lapply(questionnaires, function(q) tags$div(class = "registry-row", tags$b(q$label), pill(if (isTRUE(q$enabled)) "Active" else "Retired / inactive"), tags$p(class = "fine-print", q$source)))))
profile_editor_ui <- function(p) {
  p <- p %||% list(); pref <- as_preferences(p$preferences)
  tags$div(class = "profile-layout",
    panel("01 / A little introduction", tags$div(class = "mode-options", checkboxGroupInput("p_modes", "What are you open to? Choose either or both.", c("Find new love" = "love", "Find new friends" = "friends"), p$connection_modes %||% CONNECTION_MODES)),
      textInput("p_name", "First name or display name", p$name %||% ""), tags$div(class = "two-fields", numericInput("p_age", "Age (18+)", p$age %||% 25, 18, 100, 1), selectInput("p_gender", "My gender", GENDERS, p$gender %||% "Nonbinary")),
      conditionalPanel("(input.p_modes || []).indexOf('love') >= 0", tags$div(class = "interest-chips", checkboxGroupInput("p_interested", "For Love, I am interested in", GENDERS, p$interested %||% character()))),
      textInput("p_city", "Where I call home", p$city %||% ""), textAreaInput("p_bio", "A little about me", p$bio %||% "", placeholder = "A small joy. A good story. Something you could talk about for hours…", rows = 4), tags$p(class = "fine-print", "Up to 600 characters. Let it sound like you."),
      tags$div(class = "interest-chips", checkboxGroupInput("p_hobbies", "A few broad interests (optional)", HOBBIES, p$hobbies %||% character())), actionButton("profile_interests", "Build my interests & lifestyle story →", class = "btn-outline-primary")),
    panel("02 / Your everyday world", selectInput("p_style", "My usual style", STYLES, p$style %||% "Casual"), selectInput("p_smoking", "Smoking", c("No", "Sometimes", "Yes"), p$smoking %||% "No"), selectInput("p_goal", "In Love, I am looking for", GOALS, p$goal %||% GOALS[1]), tags$details(tags$summary("Optional private context"), selectInput("p_income", "Annual income in EUR equivalent (private)", INCOMES, p$income %||% INCOMES[1])),
      tags$div(class = "height-invitation", pill("YOUR HEIGHT STORY", "lavender"), tags$p("Everyday experiences, rather than a number on your profile."), actionButton("open_height", "Explore the optional questionnaire →", class = "btn-link")),
      tags$hr(), tags$h4("A face to your story"), tags$p(class = "fine-print", "Natural is welcome. Add up to three photos; your first is shown in discovery."), fileInput("photo_upload", "Choose a photo · PNG/JPEG, up to 5 MB", accept = c("image/png", "image/jpeg")), actionButton("upload_photo", "Add my photo", class = "btn-outline-primary"), uiOutput("my_photos")),
    tags$div(panel("03 / Room for the right person", tags$p("These preferences apply only in Love. Most guide suggestions; a firm boundary excludes people outside it."),
      conditionalPanel("(input.p_modes || []).indexOf('love') >= 0", sliderInput("pref_age", "Preferred age", 18, 100, as.numeric(unlist(pref$age))), checkboxInput("hard_age", "Make age a firm boundary", pref$hard_age),
        tags$details(tags$summary("Optional preferences"), sliderInput("pref_height", "Preferred approximate height (cm)", 100, 250, as.numeric(unlist(pref$height))), tags$p(class = "fine-print", "Uses only opted-in questionnaire estimates. Always a soft preference; missing estimates do not exclude anyone."),
          checkboxGroupInput("pref_income", "Income preference (none selected = any)", INCOMES[-1], unlist(pref$income)), checkboxInput("hard_income", "Make income a firm boundary", pref$hard_income), checkboxGroupInput("pref_styles", "Style preference (none selected = any)", STYLES, unlist(pref$styles)), checkboxInput("hard_styles", "Make style a firm boundary", pref$hard_styles)),
        selectInput("pref_smoking", "Smoking preference", c("Any", "No", "Sometimes", "Yes"), pref$smoking), checkboxInput("hard_smoking", "Make smoking a firm boundary", pref$hard_smoking), selectInput("pref_goal", "Relationship intention", c("Any", GOALS), pref$goal), checkboxInput("hard_goal", "Make intention a firm boundary", pref$hard_goal)),
      tags$hr(), checkboxInput("p_consent", "Let my future interactions help develop better matching models (optional)", isTRUE(as.logical(p$consent %||% FALSE))), actionButton("save_profile", "Save my story →", class = "btn-primary full-width"), tags$p(class = "fine-print", "You can change your intentions and preferences any time.")),
      panel("Always your choice", tags$p("You decide what to share, who to connect with, and when to begin a conversation."), actionButton("open_privacy", "Privacy & account settings →", class = "btn-link"))))
}
